	/**
	 * Default Constructor
	 */
    public PersonService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PersonEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PersonRepository.class) );
		this.validator		= applicationContext.getBean(PersonValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Person
	 */
		public Person createPerson( CreatePersonCommand command ) {

		Person entity = new Person();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPersonId( command.getPersonId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setEmail( command.getEmail() );
            entity.setDepartment( command.getDepartment() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Person {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePersonCommand
	 * @return		Person
	 */
	public Person updatePerson( UpdatePersonCommand command ) {

		Person entity = new Person();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPersonId( command.getPersonId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setEmail( command.getEmail() );
            entity.setDepartment( command.getDepartment() );
            entity.setRoleAssignments( command.getRoleAssignments() );
            entity.setOwnedPolicies( command.getOwnedPolicies() );
            entity.setCorrectiveActions( command.getCorrectiveActions() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Person {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePersonCommand
	 */
	public void delete( DeletePersonCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPersonId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Person {0} ", id );

	}

	/**
	 * Method to retrieve the Person via PersonFetchOneSummary
	 * @param 	summary PersonFetchOneSummary
	 * @return 	PersonFetchOneResponse
	 */
	public Person getPerson( PersonFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PersonFetchOneSummary arg cannot be null" );

		Person entity = null;
		UUID id = summary.getPersonId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Person using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Persons
	 *
	 * @return 	List<Person>
	 */
    public List<Person> getAllPerson() {
		List<Person> list = projector.findAll( new FindAllPersonQuery() );
		return list;
	}


	/**
	 * add RoleAssignment to RoleAssignments
	 * @param		command AssignRoleAssignmentsToPersonCommand
	 */
	public void addToRoleAssignments( AssignRoleAssignmentsToPersonCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToRoleAssignments(command.getPersonId(), command.getAddTo());
	}

	/**
	 * remove RoleAssignment from RoleAssignments
	 * @param		command RemoveRoleAssignmentsFromPersonCommand
	 */
	public void removeFromRoleAssignments( RemoveRoleAssignmentsFromPersonCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromRoleAssignments(command.getPersonId(), command.getRemoveFrom());
	}

